import {selectService,countryOptions,offerLabel} from './app-entry.js';
import {requestJson,createViewScope} from './http-client.js';
const $=id=>document.getElementById(id),money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(v/100),words=v=>v.replaceAll('_',' ');
let session=null,catalog=null,selected=null,orders=[],cursor=null,requestKey=crypto.randomUUID(),actionKey=crypto.randomUUID(),installPrompt=null;
const viewScope=createViewScope();let listGeneration=0,detailGeneration=0,mutationBusy=false,booting=false,rebootRequested=false;
const errors={NUSD_NOT_ACTIVATED:'Your scope request is saved. NUSD payment and execution are not activated.',SIGN_IN_REQUIRED:'Sign in to continue.',COUNTRY_REVIEW_REQUIRED:'Numina must review scope and country eligibility before checkout.',CONFIRMED_PAYMENT_REQUIRED:'Stripe payment confirmation is required before work can start.',PAYMENT_REVIEW_REQUIRED:'The payment needs review before delivery can be recorded.',PAYMENT_CONFIRMATION_UNAVAILABLE:'Payment confirmation is not available yet. Your request remains saved.',REVISION_CONFLICT:'This request changed. Refresh and review the latest record before trying again.',CHECKOUT_REVIEW_REQUIRED:'Check the latest request and payment status before paying again.',OPEN_REQUEST_LIMIT:'You have reached the limit of 50 open requests. Contact Numina for help.',SERVICE_UNAVAILABLE:'The service is temporarily unavailable. Your form has been kept; try again.',RATE_LIMITED:'Too many requests. Wait a minute and try again.',INVALID_INPUT:'Check the required fields and lengths before submitting.'};
function notice(text){$('app-notice').textContent=text||'';$('app-notice').hidden=!text;}
async function api(path,body){const generation=viewScope.generation;try{const data=await requestJson('/api/app/v1/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},signal:viewScope.signal,body:body?JSON.stringify(body):undefined});if(!viewScope.isCurrent(generation))throw Object.assign(new Error('Request cancelled.'),{name:'AbortError'});return data;}catch(error){if(!viewScope.isCurrent(generation))throw Object.assign(new Error('Request cancelled.'),{name:'AbortError'});if(error.status===401){clearSession();notice('Sign in again to load your current records.');}if(errors[error.code])error.message=errors[error.code];throw error;}}
function report(error){if(error.name==='AbortError')return;notice(error.name==='TimeoutError'?'The connection timed out. A submitted change may still have been saved. Refresh your records before trying again; an unchanged request uses the same retry key.':error.message||'Connection unavailable. Try again.');}
function element(tag,text,className){const e=document.createElement(tag);e.textContent=text;if(className)e.className=className;return e;}
function connectivity(){const online=navigator.onLine;$('connection-state').textContent=online?'Online · refresh for current records':'Offline · reconnect to load or save';$('request-fields').disabled=!online||!session||!catalog||mutationBusy||booting;$('refresh-orders').disabled=!online||mutationBusy||booting;$('submit-request').disabled=mutationBusy||!session||!catalog;$('more-orders').disabled=!online||!session||mutationBusy;for(const b of document.querySelectorAll('#action-form button,#checkout-button'))b.disabled=!online||!session||!selected||mutationBusy;}
function clearDetail(){detailGeneration++;selected=null;$('order-detail').hidden=true;$('checkout-button').hidden=true;$('action-form').hidden=true;for(const id of ['detail-title','detail-id','detail-brief','detail-success','detail-payment','checkout-status'])$(id).textContent='';$('order-events').replaceChildren();$('order-action').replaceChildren();$('action-note').value='';connectivity();}
function clearSession(){viewScope.reset();listGeneration++;session=null;orders=[];cursor=null;clearDetail();$('orders-list').replaceChildren();$('orders-status').textContent='Sign in to load your requests.';$('more-orders').hidden=true;$('team-view').checked=false;$('team-label').hidden=true;$('sign-in-panel').hidden=false;$('account-link').textContent='Sign in';$('account-link').href=selectService(catalog?.offers||{diagnostic:true},location.href).signInUrl;$('request-form').reset();requestKey=crypto.randomUUID();actionKey=crypto.randomUUID();connectivity();}
function renderOrders(){const list=$('orders-list');list.replaceChildren();for(const order of orders){const card=element('button','', 'order-card');card.type='button';card.append(element('strong',order.title),element('span',words(order.status),'order-status'),element('span',catalog?.offers?.[order.service]?.name||words(order.service)),element('span','Payment: '+words(order.payment.status),'order-payment'));card.addEventListener('click',()=>{if(!mutationBusy)openOrder(order.id).catch(report);});list.append(card);}$('orders-status').textContent=orders.length?orders.length+' request'+(orders.length===1?'':'s')+' loaded. Select one to view its record.':'No requests yet. Submit a workflow for scope review.';$('more-orders').hidden=!cursor;}
async function loadOrders(append=false){if(!session)return;const generation=++listGeneration,scope=viewScope.generation,query=new URLSearchParams();if($('team-view').checked)query.set('scope','team');if(append&&cursor)query.set('after',cursor);if(!append){orders=[];cursor=null;$('orders-list').replaceChildren();$('more-orders').hidden=true;}$('orders-status').textContent='Loading current requests…';try{const result=await api('orders?'+query);if(generation!==listGeneration||!viewScope.isCurrent(scope))return;orders=append?[...orders,...result.orders]:result.orders;cursor=result.next;renderOrders();}catch(error){if(generation===listGeneration&&viewScope.isCurrent(scope))$('orders-status').textContent='Current requests unavailable. Refresh to try again.';throw error;}}
function actionChoices(order){const choices=[];if(order.requestOnly||order.payment?.currency==='nusd'||catalog?.offers?.[order.service]?.requestOnly){if(session.operator&&order.status==='submitted')choices.push(['scope','Record scope review'],['decline','Decline request']);if(session.operator&&order.status==='scoped')choices.push(['decline','Decline request']);if(order.isOwner&&['submitted','scoped'].includes(order.status))choices.push(['cancel','Cancel request']);return choices;}if(session.operator){if(order.status==='submitted')choices.push(['scope','Confirm scope and eligibility'],['decline','Decline request']);if(order.status==='scoped')choices.push(['start','Start agreed work']);if(order.status==='in_progress')choices.push(['deliver','Record delivery']);}if(order.isOwner){if(order.status==='submitted')choices.push(['cancel','Cancel request']);if(order.status==='delivered')choices.push(['accept','Accept delivered work'],['request_changes','Request changes']);}return choices;}
async function openOrder(id){clearDetail();const generation=detailGeneration,scope=viewScope.generation;const [{order},{events}]=await Promise.all([api('orders/'+id),api('orders/'+id+'/events')]);if(generation!==detailGeneration||!viewScope.isCurrent(scope)||!session)return;selected=order;actionKey=crypto.randomUUID();$('order-detail').hidden=false;$('detail-title').textContent=order.title;$('detail-id').textContent=order.id+' · revision '+order.revision;$('detail-brief').textContent=order.brief;$('detail-success').textContent=order.successCriteria;const p=order.payment,requestOnly=!!(order.requestOnly||order.payment?.currency==='nusd'||catalog?.offers?.[order.service]?.requestOnly);$('detail-payment').textContent=requestOnly?'NUSD service · scope review only. No price, payment, token allocation or paid access has been created.':'Status: '+words(p.status)+'. Confirmed payments '+money(p.gross)+'; confirmed refunds '+money(p.refunded)+'.'+(p.duplicatePayment?' Multiple payments require operator review.':'');const canPay=!requestOnly&&order.isOwner&&['submitted','scoped'].includes(order.status)&&p.status==='unconfirmed';$('checkout-button').hidden=!canPay;$('checkout-status').textContent=requestOnly?'Review notes are recorded below. Payment and execution remain unavailable until the service is activated.':order.country!=='US'&&order.status==='submitted'?'Country and scope review is required before checkout.':'Payment reserves the engagement. Scope, scheduling, authorized access and confidentiality must be confirmed separately.';const list=$('order-events');list.replaceChildren();for(const e of events){const li=element('li','');li.append(element('strong',words(e.action)),element('time',new Date(e.created_at*1000).toLocaleString()),element('p',e.note));list.append(li);}const choices=actionChoices(order);$('action-form').hidden=!choices.length;$('order-action').replaceChildren(...choices.map(([value,label])=>{const op=element('option',label);op.value=value;return op;}));$('action-note').value='';connectivity();$('order-detail').scrollIntoView({behavior:'smooth',block:'start'});}
async function savedView(id,message){clearDetail();notice(message);try{await loadOrders();await openOrder(id);}catch(error){if(error.name==='AbortError'||error.status===401)return;notice(message+' The latest view could not be loaded. Refresh before making another change.');}}
$('service').addEventListener('change',()=>{if(catalog)$('service-description').textContent=catalog.offers[$('service').value].description;});
$('request-form').addEventListener('input',()=>requestKey=crypto.randomUUID());
$('request-form').addEventListener('submit',async event=>{event.preventDefault();if(mutationBusy||!session||!catalog||booting||!navigator.onLine)return;mutationBusy=true;connectivity();notice('');try{const body={idempotencyKey:requestKey,service:$('service').value,title:$('request-title').value,brief:$('request-brief').value,successCriteria:$('request-success').value,country:$('request-country').value.toUpperCase(),consent:$('request-consent').checked};const result=await api('orders',body);$('request-form').reset();$('service-description').textContent=catalog.offers[$('service').value]?.description||'';requestKey=crypto.randomUUID();await savedView(result.order.id,catalog.offers[body.service].requestOnly?'Scope request saved. Follow its review below; no payment is due.':'Request saved. Review it below and proceed to checkout when ready.');}catch(e){report(e);}finally{mutationBusy=false;connectivity();}});
$('action-note').addEventListener('input',()=>actionKey=crypto.randomUUID());$('order-action').addEventListener('change',()=>actionKey=crypto.randomUUID());
$('action-form').addEventListener('submit',async event=>{event.preventDefault();if(mutationBusy||!session||!selected||!navigator.onLine)return;const id=selected.id;mutationBusy=true;connectivity();try{await api('orders/'+id+'/actions',{action:$('order-action').value,note:$('action-note').value,revision:selected.revision,idempotencyKey:actionKey});await savedView(id,'Action saved.');}catch(e){report(e);}finally{mutationBusy=false;connectivity();}});
$('checkout-button').addEventListener('click',async()=>{if(mutationBusy||!session||!selected||!navigator.onLine)return;const id=selected.id,generation=detailGeneration;mutationBusy=true;connectivity();try{const {url}=await api('orders/'+id+'/checkout',{});if(generation!==detailGeneration||selected?.id!==id)return;const target=new URL(url);if(target.origin!=='https://book.stripe.com')throw new Error('Unexpected checkout destination.');window.location.assign(target.href);}catch(e){report(e);}finally{mutationBusy=false;connectivity();}});
$('refresh-orders').addEventListener('click',()=>{if(mutationBusy||booting)return;if(!session||!catalog){boot();return;}const id=selected?.id;Promise.all([loadOrders(),id?openOrder(id):Promise.resolve()]).catch(report);});$('more-orders').addEventListener('click',()=>{if(!mutationBusy)loadOrders(true).catch(report);});$('team-view').addEventListener('change',()=>{clearDetail();loadOrders().catch(report);});$('close-detail').addEventListener('click',clearDetail);
window.addEventListener('pagehide',()=>{clearSession();notice('');});window.addEventListener('pageshow',event=>{if(event.persisted)boot();});
window.addEventListener('online',connectivity);window.addEventListener('offline',connectivity);window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;$('install-app').hidden=false;});$('install-app').addEventListener('click',async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('install-app').hidden=true;}});
async function boot(){
 if(booting){rebootRequested=true;return;}booting=true;const scope=viewScope.generation;
 const initial=selectService(Object.fromEntries([...$('service').options].map(option=>[option.value,true])),location.href);$('service').value=initial.chosen;for(const link of document.querySelectorAll('a[href^="/signin-with-chatgpt"]'))link.href=initial.signInUrl;connectivity();
 try{
  try{const loaded=await api('catalog');if(!loaded?.offers?.diagnostic||!loaded?.offers?.audit)throw new Error('Service catalog unavailable. Refresh to try again.');catalog=loaded;const {chosen,signInUrl}=selectService(catalog.offers,location.href);$('service').replaceChildren(...Object.entries(catalog.offers).map(([id,offer])=>{const option=element('option',offerLabel(offer));option.value=id;option.defaultSelected=id===chosen;return option;}));$('service').value=chosen;for(const link of document.querySelectorAll('a[href^="/signin-with-chatgpt"]'))link.href=signInUrl;$('request-country').replaceChildren(...countryOptions().map(([code,name])=>{const option=element('option',name);option.value=code;option.defaultSelected=code==='US';return option;}));$('service-description').textContent=catalog.offers[chosen].description;const health=await api('health');$('app-health').textContent=health.status==='ready'?'Service available':'Service unavailable';if(health.paymentConfirmation!=='configured')notice('Service requests are available. Checkout confirmation is still being connected.');}
  catch(e){if(e.name==='AbortError')return;catalog=null;$('app-health').textContent='Service unavailable';report(e);}
  if(!viewScope.isCurrent(scope))return;
  try{session=await api('session');$('sign-in-panel').hidden=true;$('account-link').textContent='Sign out · '+session.email;$('account-link').href='/signout-with-chatgpt?return_to=%2Fapp';$('team-label').hidden=!session.operator;await loadOrders();}catch(e){if(e.code!=='SIGN_IN_REQUIRED')report(e);}
 }finally{booting=false;connectivity();if(rebootRequested){rebootRequested=false;void boot();}}
 if('serviceWorker'in navigator)navigator.serviceWorker.register('/app-sw.js',{scope:'/app'}).catch(()=>{});
}
boot();
